div.script:
// 
  const library = [
    {
      name: "Metroid Fusion",
      thumb: "https://images.igdb.com/igdb/image/upload/t_cover_big/co1xau.png",
      url: "https://emulatorjs.org/demo/?core=gba"
    },
    {
      name: "Wario Land 4",
      thumb: "https://images.igdb.com/igdb/image/upload/t_cover_big/co1xaz.png",
      url: "https://emulatorjs.org/demo/?core=gba"
    },
    {
      name: "Diablo",
      thumb: "https://images.igdb.com/igdb/image/upload/t_cover_big/co20u5.png",
      url: "https://d07riv.github.io/diabloweb/"
    },
    {
      name: "Spacebar Clicker",
      thumb: "https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7h.png",
      url: "https://spacebar-clicker.com"
    }
  ];

  const grid = document.getElementById('grid');
  const search = document.getElementById('search');
  const viewer = document.getElementById('game-viewer');
  const frame = document.getElementById('frame');
  const label = document.getElementById('game-label');

  function render(items) {
    grid.innerHTML = items.map(function(item) {
      const originalIndex = library.indexOf(item);
      return '<div class="game-card" onclick="openGameIndex(' + originalIndex + ')">' +
               '<img class="game-thumb" src="' + item.thumb + '" referrerpolicy="no-referrer" loading="lazy" />' +
               '<div class="game-info">' +
                 '<div class="game-title">' + item.name + '</div>' +
               '</div>' +
             '</div>';
    }).join('');
  }

  window.openGameIndex = function(index) {
    const item = library[index];
    if (!item) return;
    label.innerText = item.name;
    frame.src = item.url;
    viewer.style.display = 'flex';
  };

  window.closeGame = function() {
    viewer.style.display = 'none';
    frame.src = '';
  };

  window.toggleFS = function() {
    if (!document.fullscreenElement) {
      frame.requestFullscreen();
    } else {
      document.exitFullscreen();
    }
  };

  search.addEventListener('input', function(e) {
    const val = e.target.value.toLowerCase();
    const filtered = library.filter(function(i) {
      return i.name.toLowerCase().indexOf(val) !== -1;
    });
    render(filtered);
  });

  render(library);
//
